    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Deleted organizations whose deletion is at or before `cutoff`. */
export async function listOrgIdsDeletedBefore(
  cutoff: IsoTimestamp,
): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(isNotNull(organizations.archivedAt), lte(organizations.archivedAt, cutoff)))
    .all();
  return rows.map((row) => row.id as OrgId);
}

/** Permanently removes the organization and every row that belongs to it. */
export async function purgeOrg(orgId: OrgId): Promise<void> {
  getDb().transaction((tx) => {
    const tenantTables = [
      activityEvents,
      attachments,
      comments,
      invitations,
      invoices,
      issueLabels,
      issues,
      labels,
      members,
      notificationPreferences,
      notifications,
      projectMembers,
      projects,
      rateLimitBuckets,
      searchIndex,
      subscriptions,
      webhookDeliveries,
      webhookEndpoints,
    ];
    for (const table of tenantTables) {
      tx.delete(table).where(eq(table.orgId, orgId)).run();
    }
    tx.delete(organizationUsage).where(eq(organizationUsage.orgId, orgId)).run();
    tx.update(sessions)
      .set({ activeOrgId: null })
      .where(eq(sessions.activeOrgId, orgId))
      .run();
    tx.delete(organizations).where(eq(organizations.id, orgId)).run();
  });
}

