const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Brings a deleted workspace back inside its retention window. No `Actor`
 * exists for a deleted org, so the caller's membership is looked up here.
 */
export async function restoreOrganization(
  userId: UserId,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  const member = requireFound(
    await memberRepo.findMember(orgId, userId),
    "Organization",
    orgId,
  );
  if (member.status !== "active") throw new NotFoundError("Organization", orgId);

  if (org.archivedAt !== null) {
    const purgeAt =
      Date.parse(org.archivedAt) +
      DELETED_WORKSPACE_RETENTION_DAYS * MS_PER_DAY;
    if (Date.now() >= purgeAt) throw new NotFoundError("Organization", orgId);
  }

  assertCan(
    { userId, orgId, role: member.role },
    "org:restore",
    orgResource(orgId),
  );

  if (org.archivedAt === null) return org;

  const restored = await orgRepo.restoreOrg(orgId);

  await emit("organization.restored", {
    ...envelope(orgId, userId),
    slug: restored.slug,
  });

  return restored;
}''')
